package io.github.gerbesh.unusualcopper;

import io.github.gerbesh.unusualcopper.gameplay.*;
import io.github.gerbesh.unusualcopper.machine.*;
import io.github.gerbesh.unusualcopper.menu.RepairMenu;
import io.github.gerbesh.unusualcopper.registry.ModContent;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.Enchantments;
import net.minecraftforge.gametest.*;
import java.util.*;

@GameTestHolder(UnusualCopper.MOD_ID) @PrefixGameTestTemplate(false)
public final class RepairGameTests {
    @GameTest(template="empty",timeoutTicks=300) public static void cancelledXpAndForeignRuntimeCannotRepair(GameTestHelper h){var p=new BlockPos(123336,70,124008);PopulationGameTests.loaded(h,new WorkArea(p,p.offset(3,3,3)),()->{var level=h.getLevel();level.setBlock(p,ModContent.MACHINES.get(MachineKind.REPAIR_CRYSTAL).get().defaultBlockState(),3);var m=(CopperMachineBlockEntity)level.getBlockEntity(p);m.setOwner(UUID.randomUUID());m.energy.restore(50000);var player=EnchanterGameTests.owner(level,m,p);var item=new ItemStack(Items.DIAMOND_PICKAXE);item.setDamageValue(301);m.inventory.setStackInSlot(0,item);var menu=new RepairMenu(83,player.getInventory(),m);player.containerMenu=menu;h.assertTrue(!menu.select(UUID.randomUUID(),128,player),"Stale machine identity cannot prepare a repair");h.assertTrue(menu.select(m.runtimeIdentity,128,player),"Owner can quote");var q=menu.quote();var saved=m.inventory.serializeNBT();var xp=XpWallet.capture(player);var events=new EnchanterGameTests.XpEvents(player.getUUID(),0,m);net.minecraftforge.common.MinecraftForge.EVENT_BUS.register(events);try{h.assertTrue(!menu.confirm(m.runtimeIdentity,q.nonce(),player)&&saved.equals(m.inventory.serializeNBT())&&xp.matches(player)&&m.energy.stored()==50000,"Cancelled XP event cannot charge energy or repair for free");}finally{net.minecraftforge.common.MinecraftForge.EVENT_BUS.unregister(events);}var stranger=net.minecraftforge.common.util.FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"NoRepairAccess"));stranger.setPos(player.position());var foreignMenu=new RepairMenu(84,stranger.getInventory(),m);stranger.containerMenu=foreignMenu;h.assertTrue(!foreignMenu.select(m.runtimeIdentity,128,stranger)&&saved.equals(m.inventory.serializeNBT()),"Another player cannot use the owner's target or energy");});}
    @GameTest(template="empty") public static void repairsOnlyDurabilityAndRejectsUnbreakable(GameTestHelper h){var item=new ItemStack(Items.DIAMOND_PICKAXE);item.setDamageValue(301);item.enchant(Enchantments.UNBREAKING,3);item.setHoverName(Component.literal("Keep me"));item.getOrCreateTag().putInt("RepairCost",123);item.getOrCreateTag().putString("Witness","persistent");var before=item.copy();var q=RepairPolicy.quote(item,128);var after=RepairPolicy.apply(item,q);var a=before.save(new CompoundTag());var b=after.save(new CompoundTag());a.getCompound("tag").remove("Damage");b.getCompound("tag").remove("Damage");h.assertTrue(after.getDamageValue()==173&&a.equals(b)&&ItemStack.matches(before,item),"Only damage changes on an independent repaired copy; all other serialized data survives");item.getOrCreateTag().putBoolean("Unbreakable",true);h.assertTrue(RepairPolicy.quote(item,128)==null,"Unbreakable cannot be charged");h.assertTrue(RepairPolicy.quote(new ItemStack(Items.DIRT),128)==null&&RepairPolicy.quote(new ItemStack(Items.DIAMOND_PICKAXE),128)==null,"Non-durable and undamaged inputs cannot be charged");h.succeed();}
    @GameTest(template="empty",timeoutTicks=300) public static void personalXpAndCueAreChargedOnceWithoutCopper(GameTestHelper h){var p=new BlockPos(123080,70,124008);PopulationGameTests.loaded(h,new WorkArea(p,p.offset(3,3,3)),()->{var level=h.getLevel();level.setBlock(p,ModContent.MACHINES.get(MachineKind.REPAIR_CRYSTAL).get().defaultBlockState(),3);var m=(CopperMachineBlockEntity)level.getBlockEntity(p);m.setOwner(UUID.randomUUID());m.energy.add(50000,false);var item=new ItemStack(Items.DIAMOND_PICKAXE);item.setDamageValue(301);m.inventory.setStackInSlot(0,item);var player=EnchanterGameTests.owner(level,m,p);var menu=new RepairMenu(81,player.getInventory(),m);player.containerMenu=menu;h.assertTrue(menu.select(m.runtimeIdentity,128,player),"Prepare a bounded server quote");var q=menu.quote();h.assertTrue(q.price().cue()==12800&&q.price().xp()==32&&m.inventory.getStackInSlot(1).isEmpty(),"The quote contains only CuE and real XP points");h.assertTrue(menu.confirm(m.runtimeIdentity,q.nonce(),player)&&m.inventory.getStackInSlot(0).getDamageValue()==173&&m.energy.stored()==37200&&Math.abs(XpWallet.points(player)-968)<.0001,"One repair spends exactly its two currencies");h.assertTrue(!menu.confirm(m.runtimeIdentity,q.nonce(),player)&&m.energy.stored()==37200&&m.inventory.getStackInSlot(0).getDamageValue()==173,"Replay cannot repair or charge twice");});}
    @GameTest(template="empty",timeoutTicks=300) public static void insufficientFundsAndChangedItemNeverPartiallyCharge(GameTestHelper h){var p=new BlockPos(123208,70,124008);PopulationGameTests.loaded(h,new WorkArea(p,p.offset(3,3,3)),()->{var level=h.getLevel();level.setBlock(p,ModContent.MACHINES.get(MachineKind.REPAIR_CRYSTAL).get().defaultBlockState(),3);var m=(CopperMachineBlockEntity)level.getBlockEntity(p);m.setOwner(UUID.randomUUID());var player=EnchanterGameTests.owner(level,m,p);for(int mode=0;mode<3;mode++){m.energy.restore(mode==0?12799:50000);EnchanterGameTests.xp(player,mode==1?31:1000);var item=new ItemStack(Items.DIAMOND_PICKAXE);item.setDamageValue(301);m.inventory.setStackInSlot(0,item);var menu=new RepairMenu(82,player.getInventory(),m);player.containerMenu=menu;menu.select(m.runtimeIdentity,128,player);var nonce=menu.quote().nonce();if(mode==2)m.inventory.setStackInSlot(0,item.copy());var saved=m.inventory.serializeNBT();var xp=XpWallet.capture(player);int energy=m.energy.stored();h.assertTrue(!menu.confirm(m.runtimeIdentity,nonce,player)&&saved.equals(m.inventory.serializeNBT())&&xp.matches(player)&&energy==m.energy.stored(),"Missing currency or replaced item preserves all owned state");}});}
}
